class Solution {
public:
    int kConcatenationMaxSum(vector<int>& arr, int k) {
        const long long MOD = 1000000007;
        int n = (int)arr.size();

        // Kadane for k = 1 (single copy), clamped at 0.
        long long kadane = 0, cur = 0;
        for (int x : arr) {
            cur = max((long long)x, cur + x);
            if (cur > kadane) kadane = cur;
        }

        if (k == 1) {
            return (int)(kadane % MOD);
        }

        // Total sum of one copy.
        long long total = 0;
        for (int x : arr) total += x;

        // Maximum prefix sum of one copy.
        long long maxPref = 0, pref = 0;
        for (int x : arr) {
            pref += x;
            if (pref > maxPref) maxPref = pref;
        }

        // Maximum suffix sum of one copy.
        long long maxSuff = 0, suff = 0;
        for (int i = n - 1; i >= 0; i--) {
            suff += arr[i];
            if (suff > maxSuff) maxSuff = suff;
        }

        long long ans = kadane;
        if (total > 0) {
            long long cross = maxSuff + maxPref + (long long)(k - 2) * total;
            if (cross > ans) ans = cross;
        } else {
            long long cross = maxSuff + maxPref;
            if (cross > ans) ans = cross;
        }

        return (int)(ans % MOD);
    }
};
